const crypto = require('crypto');
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const json      = items[i].json;
  const secret    = $env.CHATWOOT_WEBHOOK_SECRET;
  const received  = json.headers['x-chatwoot-signature'];
  const timestamp = json.headers['x-chatwoot-timestamp'];

  let ok = false, expected = null, rawLen = null, rawPreview = null, err = null;
  try {
    const rawBuf = await this.helpers.getBinaryDataBuffer(i, 'data');   // 'data' = nombre de la prop binaria
    rawLen = rawBuf.length;
    rawPreview = rawBuf.toString('utf8').slice(0, 60);

    const signed = Buffer.concat([Buffer.from(`${timestamp}.`), rawBuf]);
    expected = 'sha256=' + crypto.createHmac('sha256', secret).update(signed).digest('hex');

    ok = !!received
      && expected.length === received.length
      && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(received));
  } catch (e) {
    err = String(e.message || e);
  }

  out.push({ json: { ...json, _hmac: { ok, expected, received, timestamp, rawLen, rawPreview, err } }, pairedItem: { item: i } });
}

return out;

// === DECIDIR — decide QUÉ hacer y arma la conversación (sin catálogo: eso lo inyecta 'Armar mensajes') ===
const webhookData = $('Chatwoot Webhook').first().json;
const body = webhookData.body;
const myMessageId = body.id;
const conversationId = body.conversation.id;
const accountId = body.account.id;

// F5: created_at robusto (unix int, string numérico o ISO) → siempre número
const num = (v) => {
  if (v == null) return 0;
  if (typeof v === 'number') return v;
  const n = Number(v);
  if (Number.isFinite(n)) return n;
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : 0;
};
const myCreatedAt = num(body.created_at);

const historialJson = $('Get Historial').first().json;
const rawPayload = historialJson.payload;
const allMessages = Array.isArray(rawPayload) ? rawPayload : (rawPayload && rawPayload.messages ? rawPayload.messages : []);

const isIn = (m) => m.message_type === 'incoming' || m.message_type === 0;
const isOut = (m) => (m.message_type === 'outgoing' || m.message_type === 1) && !m.private;
const hasContent = (m) => m.content && String(m.content).trim().length > 0;

const sorted = allMessages.slice().sort((a, b) => num(a.created_at) - num(b.created_at));

// DEBOUNCE (F1): el "último" es el último ENTRANTE CON TEXTO.
// Una foto que llega después de la pregunta ya no gana el "soy el último".
const incoming = sorted.filter((m) => isIn(m) && hasContent(m));
const lastIncoming = incoming.length ? incoming[incoming.length - 1] : null;
if (lastIncoming && myMessageId && lastIncoming.id !== myMessageId) {
  return [{ json: { action: 'skip', reason: 'no-soy-el-ultimo', conversationId, accountId } }];
}

// IDEMPOTENCIA (F5): ya hay respuesta posterior a mi mensaje → no repito
const repliedAfter = sorted.some((m) => isOut(m) && num(m.created_at) > myCreatedAt);
if (repliedAfter) {
  return [{ json: { action: 'skip', reason: 'ya-respondido', conversationId, accountId } }];
}

// Ráfaga del cliente = entrantes con texto desde la última salida
let lastOutIdx = -1;
for (let i = sorted.length - 1; i >= 0; i--) {
  if (isOut(sorted[i])) { lastOutIdx = i; break; }
}
const burst = sorted.slice(lastOutIdx + 1).filter((m) => isIn(m) && hasContent(m)).map((m) => m.content);
const mergedUser = burst.join('\n');

if (!mergedUser) {
  return [{ json: { action: 'skip', reason: 'sin-texto-nuevo', conversationId, accountId } }];
}

// INJECTION: regex sobre el texto agregado (red barata; Tier-1 lo duplicará)
const INJECTION_PATTERNS = [
  /ignor[aá].*(instrucciones|reglas|rol)/i,
  /olvid[aá].*(instrucciones|reglas|rol)/i,
  /nuevo rol/i,
  /ignore (previous|instructions|your)/i,
  /system prompt/i,
  /jailbreak/i,
  /\bDAN\b/,
  /pretend you are/i,
  /do anything now/i,
  /forget your instructions/i
];
if (INJECTION_PATTERNS.some((p) => p.test(mergedUser))) {
  return [{ json: { action: 'injection', conversationId, accountId } }];
}

// PRIMER MENSAJE (F3): saludo enlatado SOLO si el texto es un saludo puro.
// Primer mensaje con pregunta → process (lo contesta el LLM).
const hasOutgoing = sorted.some(isOut);
function isGreetingOnly(text) {
  const t = (text || '')
    .toLowerCase()
    .replace(/[¡!¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!t) return false;
  const G = '(hola|holis|buenas|buen dia|buen día|buenos dias|buenos días|buenas tardes|buenas noches|hey|que tal|qué tal|como andas|cómo andás|como va|cómo va|todo bien)';
  const re = new RegExp('^' + G + '( ' + G + ')*$');
  return re.test(t);
}
if (!hasOutgoing && isGreetingOnly(mergedUser)) {
  return [{ json: { action: 'primer-mensaje', conversationId, accountId } }];
}

// CAP DE RESPUESTAS POR CONVERSACIÓN (ventana rodante 24h): tope duro para floods sostenidos.
const CAP_RESPUESTAS = 25;
const nowMs = Date.now();
const botOut = sorted.filter((m) => isOut(m) && hasContent(m));
const botOut24 = botOut.filter((m) => nowMs - num(m.created_at) < 86400000);
const CAP_MARK = 'muchos mensajes en esta conversación';
if (botOut24.length >= CAP_RESPUESTAS) {
  const capYaAvisado = botOut24.some((m) => String(m.content).toLowerCase().includes(CAP_MARK));
  if (capYaAvisado) {
    return [{ json: { action: 'skip', reason: 'cap-ya-avisado', conversationId, accountId } }];
  }
  return [{ json: { action: 'cap', conversationId, accountId } }];
}

// PROCESS: armar la conversación (sin system, sin catálogo). 'Armar mensajes' le prepende el system+catálogo.
// ¿ya se le avisó al cliente que el canal es solo informativo? (buscamos el email del negocio en salientes del bot)
const avisoDado = sorted.some((m) => isOut(m) && hasContent(m) && String(m.content).toLowerCase().includes('terminalgrafica@gmail.com'));
// Últimas 3 respuestas del bot → el LLM las usa para no repetirse (action noop)
const lastBotReplies = botOut.slice(-3).map((m) => String(m.content));

const conversation = [];
const history = sorted.slice(0, lastOutIdx + 1).slice(-6);
for (const m of history) {
  if (isIn(m) && hasContent(m)) {
    conversation.push({ role: 'user', content: m.content });
  } else if (isOut(m) && hasContent(m)) {
    conversation.push({ role: 'assistant', content: m.content });
  }
}
conversation.push({ role: 'user', content: mergedUser });

return [{ json: { action: 'process', conversation, userMessage: mergedUser, avisoDado, lastBotReplies, conversationId, accountId } }];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
const TTL_MS = 10 * 60 * 1000; // 10 min — subilo si el catálogo casi no cambia

const fresh = sd.catalogo && sd.catalogoTs && (Date.now() - sd.catalogoTs) < TTL_MS;

return [{
  json: { ...input, _cacheHit: !!fresh, _catalogo: fresh ? sd.catalogo : null },
  pairedItem: { item: 0 },
}];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
const fresh = input.catalogo; // la query devuelve { catalogo }

let cat;
if (fresh) {
  cat = fresh;
  sd.catalogo = cat;
  sd.catalogoTs = Date.now();
} else {
  // la query falló (onError=continueRegularOutput) → servimos cache viejo si hay
  cat = sd.catalogo || '(catalogo no disponible)';
}

return [{
  json: { _catalogo: cat, _cacheHit: false, _stale: !fresh },
  pairedItem: { item: 0 },
}];

const decidir = $('Decidir').first().json;
const conversation = decidir.conversation || [];
const catalogo = $input.first().json._catalogo || '(catalogo no disponible)';
const systemPrompt = $('System Prompt').first().json.systemPrompt.replace('__CATALOGO__', catalogo);

const avisoNote = decidir.avisoDado
  ? 'ESTADO INTERNO (no lo menciones textualmente): al cliente YA se le avisó que este canal es solo informativo y que los pedidos se hacen por email. NO repitas ese aviso; seguí contestando normal sus consultas.'
  : 'ESTADO INTERNO (no lo menciones textualmente): al cliente TODAVÍA no se le avisó sobre el canal informativo/email.';

const lastBotReplies = decidir.lastBotReplies || [];
const repeatNote = lastBotReplies.length
  ? 'ESTADO INTERNO (no lo menciones): tus últimas respuestas en esta conversación fueron:  ' + lastBotReplies.map((r, i) => '[' + (i + 1) + '] ' + r).join('   ///   ') + '.  Si tu respuesta no agregaría nada nuevo (misma intención o información) respecto de estas, y el cliente no sumó una pregunta ni un dato nuevo, respondé con action noop.'
  : 'ESTADO INTERNO: todavía no diste ninguna respuesta en esta conversación.';

const llmMessages = [{ role: 'system', content: systemPrompt }, { role: 'system', content: avisoNote }, { role: 'system', content: repeatNote }, ...conversation];

return [{ json: { ...decidir, llmMessages }, pairedItem: { item: 0 } }];

// Parsea la salida JSON del LLM de forma tolerante. Fallback seguro = handoff.
const decidir = $('Decidir').first().json;

let raw = '';
try { raw = $input.first().json.choices[0].message.content || ''; } catch (e) { raw = ''; }

let txt = String(raw).trim();
// sacar posibles fences ```json ... ```
if (txt.startsWith('```')) {
  txt = txt.replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '').trim();
}

let action = 'handoff', reply = '', motivo = '', producto = '', variante = '';
try {
  const obj = JSON.parse(txt);
  action = String(obj.action || '').toLowerCase();
  reply = typeof obj.reply === 'string' ? obj.reply : '';
  motivo = typeof obj.motivo === 'string' ? obj.motivo : '';
  if (action === 'precio') {
    producto = typeof obj.producto === 'string' ? obj.producto.trim() : '';
    variante = (typeof obj.variante === 'string' ? obj.variante : '').replace(/\*+\s*$/, '').trim();
  }
  if (!['answer', 'handoff', 'noop', 'precio'].includes(action)) action = 'handoff';
} catch (e) {
  action = 'handoff'; reply = ''; motivo = 'respuesta del modelo ilegible';
}
if (action === 'handoff' && !motivo.trim()) motivo = 'sin motivo especificado';

// answer sin texto = no hay nada que mandar → silencio (noop), NO handoff (no escalamos ruido a un humano)
if (action === 'answer' && !reply.trim()) {
  action = 'noop';
}

// BACKSTOP DETERMINISTICO ANTI-REPETICION
// Red de seguridad para cuando el LLM NO se auto-silencia (action noop) y repite textual.
// Normaliza y compara la respuesta candidata contra las ultimas del bot (Decidir.lastBotReplies, ultimas 3).
// Umbral 2 a proposito (no 1): protege el repetir legitimo a pedido ("no me llego, repetimelo").
// Si el bot YA dijo esto ~igual 2+ veces recientes, un 3er envio es un loop -> noop.
const MAX_REPETICIONES = 2;
const normRep = (s) => String(s || '')
  .toLowerCase()
  .replace(/[*_`~#>\-]/g, ' ')
  .replace(/[¡!¿?.,;:()"']/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
if (action === 'answer' && reply.trim()) {
  const recientes = Array.isArray(decidir.lastBotReplies) ? decidir.lastBotReplies : [];
  const cand = normRep(reply);
  if (cand) {
    const repeticiones = recientes.filter((r) => normRep(r) === cand).length;
    if (repeticiones >= MAX_REPETICIONES) {
      action = 'noop';
    }
  }
}

// RAMA PRECIO — backstops deterministicos (el LLM NUNCA tipea el numero):
// - {{PRECIO}} debe aparecer exactamente una vez en el template;
// - si el LLM escribio un patron de plata igual, se descarta su texto (plantilla fija).
// producto/variante vacios NO degradan aca: Get Precio dara 0 filas -> fallback email.
let precio = null;
if (action === 'precio') {
  const template = reply;
  const marcas = (template.match(/\{\{PRECIO\}\}/g) || []).length;
  const plataRe = /(\$\s*\d)|(\d[\d.,]*\s*(pesos|ars)\b)/i;
  const forzarPlantilla = marcas !== 1 || plataRe.test(template.replace(/\{\{PRECIO\}\}/g, ''));
  precio = { producto, variante, template, forzarPlantilla };
  reply = '';
}

if (action === 'noop') reply = '';

return [{
  json: {
    action, reply, motivo, precio,
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

const decidir = $('Decidir').first().json;
const conversationMsgs = decidir.conversation || [];

// Presentar como transcript plano — evita que el LLM "continúe" el diálogo en lugar de resumirlo
const transcript = conversationMsgs.map(m => {
  const label = m.role === 'user' ? 'CLIENTE' : 'EQUIPO';
  return `[${label}]: ${m.content}`;
}).join('\n');

const noteMessages = [
  {
    role: 'system',
    content: 'Sos un asistente interno de Terminal Gráfica. NO respondas al cliente. Tu ÚNICA tarea es redactar una nota de traspaso para el asesor humano que va a tomar esta conversación.'
  },
  {
    role: 'user',
    content: `Conversación de WhatsApp:\n\n${transcript}\n\nRedactá la nota de traspaso. Incluí:\n- Qué quiere el cliente (una línea)\n- Datos mencionados (producto, cantidad, formato, etc.) — SOLO lo que el cliente dijo explícitamente, no inventes datos ni precios\n- Próximo paso sugerido para el asesor\n\nMáximo 5 líneas. Tono directo, para uso interno.`
  }
];

return [{
  json: {
    noteMessages,
    conversationId: decidir.conversationId,
    accountId: decidir.accountId
  }
}];

// Rama Fail del Guardrails Tier-2. Distingue una VIOLACIÓN REAL (jailbreak/topical
// flaggeado por el modelo) de una CAÍDA del modelo-guard (executionFailed) o un item
// de error del nodo. Fail-open ante caída: no penaliza, deja seguir al LLM principal
// (que ya degrada a handoff si OpenRouter está caído).
const j = $input.first().json;
const checks = Array.isArray(j.checks) ? j.checks : [];
const violated = checks.filter((c) => c && c.triggered && !c.executionFailed);
const realViolation = violated.length > 0;
// reason = nombre del guard que disparó (jailbreak | topicalAlignment)
const reason = realViolation ? String(violated[0].name || 'tier2') : 'model_error';

const b = $('Chatwoot Webhook').first().json.body;
const sid = b.sender?.id ?? b.conversation?.meta?.sender?.id ?? '';
const decidir = $('Decidir').first().json;

return [{
  json: {
    realViolation,
    reason,
    senderKey: String(sid),
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

// Rama precio: inyeccion deterministica desde bot.variantes (mismas filas que el
// motor del mostrador — nunca recalcular = no precio fantasma). El LLM nunca ve
// reglas ni tipea montos; aca se decide TODO en una escalera deterministica:
//   override / 2+ reglas de cantidad / precio $0  -> sin numero (email)
//   exactamente 1 regla de cantidad               -> tabla de rangos verbatim + caveat
//   sin reglas                                    -> numero limpio
//   resto (descuentos/adicionales)                -> numero de lista + caveat neutro
// Los quantity_range del ruleset real son confirmation=false y REEMPLAZAN el
// precio -> la tabla verbatim es exactamente lo que cobra el mostrador.
const parsear = $('Parsear Respuesta').first().json;
const decidir = $('Decidir').first().json;
const p = parsear.precio || {};
const rows = $input.all().map((i) => i.json).filter((r) => r && r.precio_lista !== undefined);
// Item de error de Get Precio (onError continueRegularOutput): distinguir fallo SQL
// de un no-match real en la telemetria (el cliente recibe el mismo fallback igual).
const errItem = $input.all().find((i) => i.json && i.json.error);

const DIAS_FRESCURA = 30;
const MAX_RANGOS = 6;
const CAVEAT = ' (precio de lista; el precio final del trabajo te lo confirma el equipo)';
const fmt = (n) => '$' + new Intl.NumberFormat('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n));

let estado, row = null, rangos = null;
if (rows.length === 1) {
  row = rows[0];
  const nQr = Number(row.n_reglas_cantidad) || 0;
  let raw = row.rangos_cantidad;
  if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }

  if (row.tiene_override) {
    estado = 'fallback: override';
  } else if (nQr > 1) {
    // >1 regla de cantidad: el motor resuelve precedencia de scope que aca no
    // replicamos -> una tabla elegida al azar seria mentirosa.
    estado = 'fallback: qr_multiple';
  } else if (nQr === 1) {
    const ok = Array.isArray(raw) && raw.length > 0 && raw.length <= MAX_RANGOS
      && raw.every((r) => r && Number(r.value) > 0 && Number(r.minQty) >= 1);
    estado = ok ? 'ok_rangos' : 'fallback: rangos_invalidos';
    if (ok) rangos = [...raw].sort((a, b) => Number(a.minQty) - Number(b.minQty));
  } else if (!(Number(row.precio_lista) > 0)) {
    // Variantes reales con precio 0 en el catalogo (ej. Papel Vegetal x10): un
    // "$0,00" seria absurdo -> cotiza el equipo.
    estado = 'fallback: precio_cero';
  } else {
    const ts = Date.parse(row.precio_actualizado);
    const fresco = Number.isFinite(ts) && Date.now() - ts <= DIAS_FRESCURA * 86400000;
    estado = !fresco ? 'fallback: stale' : row.tiene_reglas ? 'ok_caveat' : 'ok';
  }

  // BACKSTOP DOBLE FAZ: pedido d/f sobre variante cuyo nombre NO es d/f -> el
  // numero/tabla (simple faz) sub-cotizaria (DORSO 50% OFF encarece) -> sin numero.
  if (estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') {
    const pidioDF = /doble\s*faz|d\s*\/\s*f|frente\s*y\s*dorso|de\s+los\s+dos\s+lados|ambas\s+caras/i.test(decidir.userMessage || '');
    const varianteEsDF = /doble|dorso|d\s*\/\s*f/i.test(String(row.variante || '') + ' ' + String(p.variante || ''));
    if (pidioDF && !varianteEsDF) estado = 'fallback: dorso';
  }
} else {
  estado = errItem ? 'fallback: sql_error' : rows.length === 0 ? 'fallback: sin_match' : 'fallback: ambiguo';
}

let reply;
if (estado === 'ok' || estado === 'ok_caveat') {
  const monto = fmt(row.precio_lista) + (estado === 'ok_caveat' ? CAVEAT : '');
  const plantilla = p.producto && p.variante
    ? 'La opción ' + p.variante + ' de ' + p.producto + ' sale ' + monto + '.'
    : 'Sale ' + monto + '.';
  reply = p.forzarPlantilla || !p.template ? plantilla : p.template.split('{{PRECIO}}').join(monto);
} else if (estado === 'ok_rangos') {
  // SIEMPRE plantilla forzada: una tabla no entra en un {{PRECIO}} en medio de
  // oracion. Formato guion-por-linea (el mismo que el prompt usa para enumerar).
  const unidad = row.unidad ? String(row.unidad).trim().toLowerCase() : '';
  const encab = (p.variante && p.producto ? p.variante + ' de ' + p.producto : 'Ese producto')
    + ', precio de lista' + (unidad ? ' por ' + unidad : '') + ' según cantidad:';
  const lineas = rangos.map((r) => {
    const desde = Number(r.minQty);
    const hasta = r.maxQty === null || r.maxQty === undefined ? null : Number(r.maxQty);
    const rot = hasta === null ? desde + ' o más' : desde === hasta ? String(desde) : desde + ' a ' + hasta;
    return '- ' + rot + ': ' + fmt(r.value) + ' c/u';
  });
  reply = encab + '\n' + lineas.join('\n') + '\nEl precio final del trabajo te lo confirma el equipo.';
} else {
  // Fallback deterministico = redirect a email honesto, respetando la primera mencion (avisoDado).
  const mail = decidir.avisoDado ? 'a nuestro mail' : 'a terminalgrafica@gmail.com';
  const prod = p.producto ? 'de ' + p.producto + ' ' : '';
  reply = 'El precio ' + prod + 'te lo cotiza el equipo. Escribinos ' + mail + ' con el detalle y te pasan el número.';
}

return [{
  json: {
    reply,
    estado,
    productoResuelto: row ? row.producto_id : null,
    filasSql: rows.length,
    conversationId: parsear.conversationId,
    accountId: parsear.accountId,
    userMessage: parsear.userMessage,
    notas: (p.producto || '?') + ' | ' + (p.variante || '?') + ' | ' + estado
      + ((estado === 'ok' || estado === 'ok_caveat') && p.forzarPlantilla ? ' (plantilla forzada)' : '')
      + (errItem ? ' [' + String(errItem.json.error.message || errItem.json.error).slice(0, 120) + ']' : ''),
  },
  pairedItem: { item: 0 },
}];
